Siap! 🚀 Ini game platformer Rani—lompat ke benda yang energinya cocok, kumpulkan 10 yang benar buat memulihkan reaktor!

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Gravitasi Rani: Reaktor yang Dicuri</title>
<script type="application/json" id="aisys-story">
{
  "title": "Gravitasi Rani: Reaktor yang Dicuri",
  "hero": { "name": "Rani", "emoji": "🧑‍🚀", "desc": "Siswi SMA yang bisa mengendalikan gravitasi" },
  "world": { "name": "Laboratorium Sekolah Masa Depan", "emoji": "🧪" },
  "mood": { "from": "#1e3a8a", "to": "#0f766e" },
  "prolog": [
    { "text": "Rani, siswi SMA dengan kekuatan mengendalikan gravitasi, berlatih di laboratorium sekolah masa depan yang penuh alat canggih.", "emoji": "🌟" },
    { "text": "Suatu hari reaktor energi lab dicuri! Pelakunya Profesor Entropi—yang ternyata guru fisika Rani sendiri.", "emoji": "👾" },
    { "text": "Bantu Rani melompat dan mengumpulkan benda sesuai jenis energinya untuk memulihkan reaktor.", "emoji": "🎯" }
  ],
  "goal": { "text": "Kumpulkan 10 benda dengan jenis energi yang benar" },
  "ending": {
    "menang": { "text": "Reaktor pulih dan lab kembali menyala! Tapi Profesor Entropi kabur—Rani bersumpah akan menyelidiki ke mana gurunya pergi.", "emoji": "🏆" },
    "kalah": { "text": "Reaktor padam dan Rani terjatuh. Tapi seorang pahlawan sejati selalu bangkit—ayo coba lagi!", "emoji": "💫" }
  }
}
</script>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #0b1020; font-family: 'Segoe UI', system-ui, sans-serif; }
  #wrap { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; }
  canvas { display: block; background: #0b1020; touch-action: none; }
  #touch { position: fixed; inset: 0; pointer-events: none; }
  .btn { position: absolute; pointer-events: auto; width: 68px; height: 68px; border-radius: 50%;
    background: rgba(255,255,255,0.12); border: 2px solid rgba(255,255,255,0.35); color: #fff;
    font-size: 26px; display: flex; align-items: center; justify-content: center; user-select: none;
    -webkit-user-select: none; backdrop-filter: blur(4px); }
  .btn:active { background: rgba(255,255,255,0.3); }
  #bLeft { left: 18px; bottom: 24px; }
  #bRight { left: 100px; bottom: 24px; }
  #bJump { right: 24px; bottom: 24px; width: 84px; height: 84px; font-size: 20px; }
  #mute { position: fixed; top: 12px; right: 12px; width: 44px; height: 44px; border-radius: 10px;
    background: rgba(255,255,255,0.12); border: 1px solid rgba(255,255,255,0.3); color: #fff;
    font-size: 18px; cursor: pointer; pointer-events: auto; z-index: 10; }
</style>
</head>
<body>
<div id="wrap"><canvas id="cv"></canvas></div>
<div id="touch">
  <div class="btn" id="bLeft">◀</div>
  <div class="btn" id="bRight">▶</div>
  <div class="btn" id="bJump">LOMPAT</div>
</div>
<button id="mute">🔊</button>
<script>
(function(){
"use strict";
const W = 960, H = 540;
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
let scale = 1, offX = 0, offY = 0;

function resize(){
  const ww = window.innerWidth, wh = window.innerHeight;
  scale = Math.min(ww / W, wh / H);
  offX = (ww - W * scale) / 2;
  offY = (wh - H * scale) / 2;
  cv.width = ww; cv.height = wh;
  cv.style.width = ww + 'px'; cv.style.height = wh + 'px';
}
window.addEventListener('resize', resize);
resize();

// ---------- AUDIO ----------
let audioCtx = null, muted = false;
function unlockAudio(){
  if (!audioCtx) { try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){} }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function beep(freq, dur, type, vol){
  if (!audioCtx || muted) return;
  const o = audioCtx.createOscillator(), g = audioCtx.createGain();
  o.type = type || 'sine'; o.frequency.value = freq;
  g.gain.setValueAtTime(vol || 0.15, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(); o.stop(audioCtx.currentTime + dur);
}
function sfxCorrect(){ beep(660, 0.12, 'triangle', 0.18); setTimeout(()=>beep(990,0.15,'triangle',0.15),80); }
function sfxWrong(){ beep(180, 0.25, 'sawtooth', 0.15); }
function sfxJump(){ beep(520, 0.1, 'square', 0.1); }
function sfxWin(){ [523,659,784,1047].forEach((f,i)=>setTimeout(()=>beep(f,0.2,'triangle',0.18), i*130)); }
function sfxLose(){ [400,320,240,160].forEach((f,i)=>setTimeout(()=>beep(f,0.25,'sawtooth',0.15), i*150)); }
document.getElementById('mute').addEventListener('click', function(e){
  e.stopPropagation(); unlockAudio(); muted = !muted;
  this.textContent = muted ? '🔇' : '🔊';
});
window.addEventListener('pointerdown', unlockAudio, { once: false });

// ---------- DATA SOAL ----------
// Setiap contoh punya jawaban benar yang jelas: 'kinetik' atau 'potensial'
const BANK = [
  { teks: "Bola menggelinding",       jawab: "kinetik",   why: "Benda bergerak punya energi kinetik." },
  { teks: "Batu di atas lemari",      jawab: "potensial", why: "Posisi tinggi menyimpan energi potensial." },
  { teks: "Air terjun jatuh",         jawab: "kinetik",   why: "Air yang bergerak cepat punya energi kinetik." },
  { teks: "Anak panah di busur",      jawab: "potensial", why: "Busur terentang menyimpan energi potensial elastis." },
  { teks: "Mobil melaju di jalan",    jawab: "kinetik",   why: "Massa yang bergerak memiliki energi kinetik." },
  { teks: "Buah mangga di dahan",     jawab: "potensial", why: "Ketinggian dari tanah memberi energi potensial." },
  { teks: "Angin bertiup kencang",    jawab: "kinetik",   why: "Udara bergerak memiliki energi kinetik." },
  { teks: "Pegas tertekan",           jawab: "potensial", why: "Pegas tertekan menyimpan energi potensial elastis." },
  { teks: "Pelari sedang sprint",     jawab: "kinetik",   why: "Tubuh yang bergerak punya energi kinetik." },
  { teks: "Buku di rak atas",         jawab: "potensial", why: "Benda diam di ketinggian tetap punya energi potensial." }
];

// ---------- STATE ----------
const G = {
  state: 'mulai', // mulai, main, menang, kalah
  score: 0, nyawa: 3, benar: 0, target: 10,
  targetEnergi: 'kinetik',
  waktu: 0, feedback: null, feedbackT: 0,
  partikel: []
};

const player = { x: 120, y: 380, w: 34, h: 46, vx: 0, vy: 0, onGround: false, invuln: 0 };
const GRAV = 1800, MOVE = 260, JUMP = 640;

// Platform: {x,y,w,h}
const platforms = [
  { x: 0,   y: 480, w: 960, h: 60 },   // lantai
  { x: 180, y: 380, w: 150, h: 18 },
  { x: 420, y: 300, w: 150, h: 18 },
  { x: 660, y: 380, w: 150, h: 18 },
  { x: 300, y: 200, w: 140, h: 18 },
  { x: 600, y: 200, w: 140, h: 18 }
];

let items = []; // {x,y,w,h,teks,jawab,why,aktif}
let soalPool = [];

function shuffle(a){ for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];} return a; }

function spawnItems(){
  items = [];
  soalPool = shuffle(BANK.slice());
  const spots = [
    {x: 220, y: 330}, {x: 470, y: 250}, {x: 710, y: 330},
    {x: 340, y: 150}, {x: 640, y: 150}, {x: 500, y: 430}
  ];
  for (let i = 0; i < spots.length; i++){
    const s = soalPool[i % soalPool.length];
    items.push({ x: spots[i].x, y: spots[i].y, w: 90, h: 34, teks: s.teks, jawab: s.jawab, why: s.why, aktif: true, bob: Math.random()*6 });
  }
}

function resetGame(){
  G.score = 0; G.nyawa = 3; G.benar = 0; G.waktu = 0;
  G.feedback = null; G.feedbackT = 0; G.partikel = [];
  G.targetEnergi = 'kinetik';
  player.x = 120; player.y = 380; player.vx = 0; player.vy = 0; player.invuln = 0;
  spawnItems();
  G.state = 'main';
}

// ---------- INPUT ----------
const keys = {};
window.addEventListener('keydown', e => {
  if (['ArrowLeft','ArrowRight','ArrowUp','Space','KeyA','KeyD','KeyW'].includes(e.code)) e.preventDefault();
  keys[e.code] = true;
  if ((e.code === 'Space' || e.code === 'ArrowUp' || e.code === 'KeyW') && G.state === 'mulai') { unlockAudio(); resetGame(); }
  if (G.state === 'menang' || G.state === 'kalah') {
    if (e.code === 'Space' || e.code === 'Enter') { unlockAudio(); resetGame(); }
  }
});
window.addEventListener('keyup', e => { keys[e.code] = false; });

const touch = { left: false, right: false, jump: false };
function bindBtn(id, key){
  const el = document.getElementById(id);
  const on = e => { e.preventDefault(); unlockAudio(); touch[key] = true;
    if (G.state === 'mulai') resetGame();
    else if (G.state === 'menang' || G.state === 'kalah') resetGame(); };
  const off = e => { e.preventDefault(); touch[key] = false; };
  el.addEventListener('touchstart', on, {passive:false});
  el.addEventListener('touchend', off, {passive:false});
  el.addEventListener('mousedown', on);
  el.addEventListener('mouseup', off);
  el.addEventListener('mouseleave', off);
}
bindBtn('bLeft','left'); bindBtn('bRight','right'); bindBtn('bJump','jump');

// ---------- LOGIKA ----------
function update(dt){
  if (G.state !== 'main') return;
  G.waktu += dt;

  // gerak horizontal
  let dir = 0;
  if (keys['ArrowLeft'] || keys['KeyA'] || touch.left) dir -= 1;
  if (keys['ArrowRight'] || keys['KeyD'] || touch.right) dir += 1;
  player.vx = dir * MOVE;

  // lompat
  const jumpPressed = keys['Space'] || keys['ArrowUp'] || keys['KeyW'] || touch.jump;
  if (jumpPressed && player.onGround){
    player.vy = -JUMP; player.onGround = false; sfxJump();
  }

  // fisika
  player.vy += GRAV * dt;
  player.x += player.vx * dt;
  player.y += player.vy * dt;

  // batas kiri-kanan
  if (player.x < 0) player.x = 0;
  if (player.x + player.w > W) player.x = W - player.w;

  // tabrakan platform (hanya dari atas)
  player.onGround = false;
  for (const p of platforms){
    if (player.x + player.w > p.x && player.x < p.x + p.w){
      if (player.vy >= 0 && player.y + player.h <= p.y + 20 && player.y + player.h >= p.y){
        player.y = p.y - player.h; player.vy = 0; player.onGround = true;
      }
    }
  }
  // jatuh ke bawah
  if (player.y > H + 100){
    player.x = 120; player.y = 380; player.vy = 0;
    G.nyawa--; sfxWrong();
    if (G.nyawa <= 0) { G.state = 'kalah'; sfxLose(); if(window.AISYS&&AISYS.end)AISYS.end("kalah"); }
  }

  if (player.invuln > 0) player.invuln -= dt;

  // tabrakan item
  for (const it of items){
    if (!it.aktif) continue;
    if (player.x + player.w > it.x && player.x < it.x + it.w &&
        player.y + player.h > it.y && player.y < it.y + it.h){
      it.aktif = false;
      if (it.jawab === G.targetEnergi){
        G.score += 100; G.benar++;
        G.feedback = { teks: "BENAR! " + it.why, warna: "#22c55e" };
        G.feedbackT = 2;
        sfxCorrect();
        for (let k=0;k<12;k++) G.partikel.push({x:it.x+it.w/2,y:it.y+it.h/2,vx:(Math.random()-0.5)*300,vy:(Math.random()-0.5)*300,life:0.6,c:'#22c55e'});
        // ganti target tiap 3 benar
        if (G.benar % 3 === 0) G.targetEnergi = G.targetEnergi === 'kinetik' ? 'potensial' : 'kinetik';
        if (G.benar >= G.target){ G.state = 'menang'; sfxWin(); if(window.AISYS&&AISYS.end)AISYS.end("menang"); }
      } else {
        G.score = Math.max(0, G.score - 40);
        G.feedback = { teks: "SALAH. " + it.why, warna: "#ef4444" };
        G.feedbackT = 2;
        sfxWrong();
        if (player.invuln <= 0){ G.nyawa--; player.invuln = 1.2; }
        if (G.nyawa <= 0){ G.state = 'kalah'; sfxLose(); if(window.AISYS&&AISYS.end)AISYS.end("kalah"); }
      }
    }
  }

  // respawn item yang habis
  if (items.every(it => !it.aktif)){
    spawnItems();
  }

  // feedback timer
  if (G.feedbackT > 0){ G.feedbackT -= dt; if (G.feedbackT <= 0) G.feedback = null; }

  // partikel
  for (const p of G.partikel){ p.x += p.vx*dt; p.y += p.vy*dt; p.vy += 400*dt; p.life -= dt; }
  G.partikel = G.partikel.filter(p => p.life > 0);
}

// ---------- GAMBAR ----------
function roundRect(x,y,w,h,r){
  ctx.beginPath();
  ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath();
}

function drawBackground(){
  const g = ctx.createLinearGradient(0,0,0,H);
  g.addColorStop(0, '#1e3a8a'); g.addColorStop(1, '#0f766e');
  ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
  // panel lab
  ctx.globalAlpha = 0.08; ctx.fillStyle = '#fff';
  for (let i=0;i<8;i++){ roundRect(60+i*110, 60, 80, 120, 10); ctx.fill(); }
  ctx.globalAlpha = 1;
  // lampu
  for (let i=0;i<6;i++){
    const x = 100 + i*150, y = 40;
    ctx.fillStyle = 'rgba(255,255,255,0.15)';
    ctx.beginPath(); ctx.arc(x,y,6,0,Math.PI*2); ctx.fill();
  }
}

function drawPlatforms(){
  for (const p of platforms){
    const g = ctx.createLinearGradient(0,p.y,0,p.y+p.h);
    g.addColorStop(0,'#38bdf8'); g.addColorStop(1,'#0ea5e9');
    ctx.fillStyle = g;
    roundRect(p.x, p.y, p.w, p.h, 8); ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.4)'; ctx.lineWidth = 2; ctx.stroke();
  }
}

function drawPlayer(){
  if (player.invuln > 0 && Math.floor(G.waktu*20)%2===0) return;
  const cx = player.x + player.w/2, cy = player.y + player.h/2;
  // aura gravitasi
  ctx.save();
  ctx.globalAlpha = 0.25;
  const gg = ctx.createRadialGradient(cx,cy,4,cx,cy,40);
  gg.addColorStop(0,'#a78bfa'); gg.addColorStop(1,'rgba(167,139,250,0)');
  ctx.fillStyle = gg; ctx.beginPath(); ctx.arc(cx,cy,40,0,Math.PI*2); ctx.fill();
  ctx.restore();
  // badan
  ctx.fillStyle = '#a78bfa';
  roundRect(player.x, player.y, player.w, player.h, 8); ctx.fill();
  ctx.strokeStyle = '#fff'; ctx.lineWidth = 2; ctx.stroke();
  // kepala
  ctx.fillStyle = '#fde68a';
  ctx.beginPath(); ctx.arc(cx, player.y+10, 10, 0, Math.PI*2); ctx.fill();
  // mata
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(cx-4, player.y+9, 2, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(cx+4, player.y+9, 2, 0, Math.PI*2); ctx.fill();
}

function drawItems(){
  for (const it of items){
    if (!it.aktif) continue;
    const bob = Math.sin(G.waktu*3 + it.bob) * 4;
    const y = it.y + bob;
    const g = ctx.createLinearGradient(it.x, y, it.x, y+it.h);
    g.addColorStop(0,'#fbbf24'); g.addColorStop(1,'#f59e0b');
    ctx.fillStyle = g;
    ctx.shadowColor = '#fbbf24'; ctx.shadowBlur = 12;
    roundRect(it.x, y, it.w, it.h, 8); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = 'rgba(255,255,255,0.6)'; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.fillStyle = '#1e293b'; ctx.font = 'bold 11px system-ui'; ctx.textAlign = 'center';
    ctx.fillText(it.teks, it.x + it.w/2, y + it.h/2 + 4);
  }
}

function drawHUD(){
  // panel atas
  ctx.fillStyle = 'rgba(15,23,42,0.6)';
  roundRect(12, 12, 420, 62, 12); ctx.fill();
  ctx.textAlign = 'left';
  ctx.fillStyle = '#fff'; ctx.font = 'bold 16px system-ui';
  ctx.fillText('Skor: ' + G.score, 26, 36);
  ctx.fillText('Nyawa: ' + '❤️'.repeat(Math.max(0,G.nyawa)), 26, 60);
  // target
  ctx.fillStyle = 'rgba(15,23,42,0.6)';
  roundRect(W-300, 12, 288, 62, 12); ctx.fill();
  ctx.textAlign = 'right';
  ctx.fillStyle = '#fff'; ctx.font = 'bold 14px system-ui';
  ctx.fillText('Cari benda berenergi:', W-26, 34);
  const label = G.targetEnergi === 'kinetik' ? 'KINETIK (bergerak)' : 'POTENSIAL (posisi/tinggi)';
  ctx.fillStyle = G.targetEnergi === 'kinetik' ? '#38bdf8' : '#f472b6';
  ctx.font = 'bold 18px system-ui';
  ctx.fillText(label, W-26, 58);
  // progres
  ctx.fillStyle = 'rgba(15,23,42,0.6)';
  roundRect(12, H-52, 260, 40, 10); ctx.fill();
  ctx.textAlign = 'left'; ctx.fillStyle = '#fff'; ctx.font = 'bold 14px system-ui';
  ctx.fillText('Benar: ' + G.benar + ' / ' + G.target, 26, H-26);
  // watermark
  ctx.globalAlpha = 0.35; ctx.fillStyle = '#fff'; ctx.font = '12px system-ui';
  ctx.textAlign = 'center'; ctx.fillText('AISYS HTML5 Engine', W/2, H-14);
  ctx.globalAlpha = 1;
}

function drawFeedback(){
  if (!G.feedback) return;
  ctx.globalAlpha = Math.min(1, G.feedbackT);
  ctx.fillStyle = 'rgba(15,23,42,0.85)';
  roundRect(W/2-260, H-140, 520, 52, 12); ctx.fill();
  ctx.fillStyle = G.feedback.warna; ctx.font = 'bold 15px system-ui'; ctx.textAlign = 'center';
  ctx.fillText(G.feedback.teks, W/2, H-108);
  ctx.globalAlpha = 1;
}

function drawPartikel(){
  for (const p of G.partikel){
    ctx.globalAlpha = Math.max(0, p.life);
    ctx.fillStyle = p.c;
    ctx.beginPath(); ctx.arc(p.x, p.y, 4, 0, Math.PI*2); ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawStart(){
  ctx.fillStyle = 'rgba(11,16,32,0.85)'; ctx.fillRect(0,0,W,H);
  ctx.textAlign = 'center';
  ctx.fillStyle = '#a78bfa'; ctx.font = 'bold 40px system-ui';
  ctx.fillText('Gravitasi Rani', W/2, 150);
  ctx.fillStyle = '#fff'; ctx.font = 'bold 20px system-ui';
  ctx.fillText('Reaktor yang Dicuri', W/2, 185);
  ctx.fillStyle = '#cbd5e1'; ctx.font = '16px system-ui';
  ctx.fillText('Lompat ke benda yang energinya COCOK dengan target di kanan atas.', W/2, 250);
  ctx.fillText('Kinetik = benda bergerak. Potensial = benda di ketinggian/tertekan.', W/2, 278);
  ctx.fillText('Kumpulkan 10 benda benar. Salah 3x atau jatuh = kalah.', W/2, 306);
  ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 18px system-ui';
  ctx.fillText('Tekan SPASI / tombol LOMPAT untuk mulai', W/2, 380);
  ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.font = '13px system-ui';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, 470);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, 492);
}

function drawEnd(menang){
  ctx.fillStyle = 'rgba(11,16,32,0.88)'; ctx.fillRect(0,0,W,H);
  ctx.textAlign = 'center';
  ctx.fillStyle = menang ? '#22c55e' : '#ef4444';
  ctx.font = 'bold 44px system-ui';
  ctx.fillText(menang ? '🏆 REAKTOR PULIH!' : '💫 COBA LAGI!', W/2, 200);
  ctx.fillStyle = '#fff'; ctx.font = '18px system-ui';
  ctx.fillText('Skor akhir: ' + G.score + '  |  Benda benar: ' + G.benar, W/2, 260);
  ctx.fillStyle = '#cbd5e1'; ctx.font = '16px system-ui';
  ctx.fillText(menang ? 'Profesor Entropi kabur—Rani bersumpah menyelidiki!' : 'Reaktor padam, tapi pahlawan sejati selalu bangkit.', W/2, 300);
  ctx.fillStyle = '#fbbf24'; ctx.font = 'bold 18px system-ui';
  ctx.fillText('Tekan SPASI untuk main lagi', W/2, 380);
  ctx.fillStyle = 'rgba(255,255,255,0.5)'; ctx.font = '13px system-ui';
  ctx.fillText('Built with AISYS HTML5 Engine', W/2, 470);
  ctx.fillText('STIKOM YOS SUDARSO', W/2, 492);
}

function render(){
  ctx.setTransform(1,0,0,1,0,0);
  ctx.clearRect(0,0,cv.width,cv.height);
  ctx.setTransform(scale,0,0,scale,offX,offY);
  ctx.save();
  ctx.beginPath(); ctx.rect(0,0,W,H); ctx.clip();

  drawBackground();
  drawPlatforms();
  drawItems();
  drawPlayer();
  drawPartikel();
  drawHUD();
  drawFeedback();

  if (G.state === 'mulai') drawStart();
  else if (G.state === 'menang') drawEnd(true);
  else if (G.state === 'kalah') drawEnd(false);

  ctx.restore();
}

// ---------- LOOP ----------
let last = performance.now();
function loop(now){
  let dt = (now - last) / 1000; last = now;
  if (dt > 0.05) dt = 0.05;
  update(dt);
  render();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

})();
</script>
